INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l57','cool off','',NULL,'/kuːl ɔːf/','I stopped to let the car cool off.','我停下车让它冷却一下。','Give the engine a moment to cool off.','让发动机凉一会儿。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l57','be absorbed in','',NULL,'/bi əbˈzɔːrbd ɪn/','My father was absorbed in his new life.','父亲全身心投入新生活。','She was absorbed in her painting.','她专心地画画。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l57','land up','',NULL,'/lænd ʌp/','I landed up at the same corner again.','我又回到了同一个拐角。','They landed up in the wrong town.','他们最后到了错的镇子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l57','on one''s own','',NULL,'/ɑːn wʌnz oʊn/','He made me promise to go on my own.','他要我答应独自去。','She finished the project on her own.','她独力完成了项目。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp1','choice','{"stem":"\"When I returned, the village ___ already disappeared under the lake.\"(过去完成时,填助动词)","options":["would","has","was","had"],"answer_index":3,"stem_cn":"我回来时,村子早已消失在湖底。","explanation_cn":"过去完成时 had + 过去分词,表在“我回来”这一过去动作之前就已发生。✓ the village had already disappeared. ✗ has(现在完成)/ was / would:回溯更早的过去用 had。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp1','choice','{"stem":"\"The valley ___ been submerged long before I came back.\"(过去完成时的被动:早已被淹,填助动词)","options":["were","was","had","has"],"answer_index":2,"stem_cn":"早在我回来前很久,山谷就已被淹没。","explanation_cn":"过去完成时的被动 had + been + 过去分词,“早已被淹”。✓ The valley had been submerged. ✗ has / was(缺 had 无法表更早)/ were:此处用 had been。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp1','choice','{"stem":"\"I was lost, though my father ___ described every milestone to me.\"(过去完成时,表更早发生)","options":["was","has","would have","had"],"answer_index":3,"stem_cn":"我迷了路,尽管父亲早把每个路标都对我描述过。","explanation_cn":"过去完成时,表比“我迷路”更早发生的动作。✓ my father had described every milestone. ✗ has / was / would have:回溯更早的过去用 had。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp2','choice','{"stem":"\"I ___ expected to be near my objective by now, but I was lost.\"(过去想做/原以为而未成:用过去完成时 + expect,填助动词)","options":["was","had","would","have"],"answer_index":1,"stem_cn":"我本以为这时已接近目的地,却迷了路。","explanation_cn":"had expected to do,表过去原以为/原打算而未成的事。✓ I had expected to be near my objective. ✗ have / was / would:用过去完成时 had expected。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp2','choice','{"stem":"\"I bought maps I ___ thought I would not need on the last stage.\"(过去完成时表“原以为”)","options":["was","did","had","have"],"answer_index":2,"stem_cn":"我买了些原以为最后一段用不上的地图。","explanation_cn":"过去完成时表“原以为”,had thought。✓ maps I had thought I would not need. ✗ have / was / did:此处用 had thought。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp2','choice','{"stem":"\"My father always ___ to go back one day, but only for a visit.\"(过去的打算“总打算做…”,填动词过去式)","options":["meant","meaning","means","mean"],"answer_index":0,"stem_cn":"父亲总打算有朝一日回去,但只为探望。","explanation_cn":"mean to do,“打算做”;叙事在过去,用过去式 meant。✓ always meant to go back. ✗ means / meaning / mean:过去的打算用过去式 meant。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp3','choice','{"stem":"\"I ___ have taken a wrong turning somewhere, for I was lost.\"(对过去的推测“一定…了”)","options":["would","must","can","need"],"answer_index":1,"stem_cn":"我一定是在什么地方拐错了弯,所以迷了路。","explanation_cn":"对过去的肯定推测“一定…了”用 must + have + 过去分词。✓ I must have taken a wrong turning. ✗ can / would / need:表肯定推测用 must。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp3','choice','{"stem":"\"The stranger ___ have misunderstood me, I thought, so I repeated the name.\"(对过去的推测,填表推测的词)","options":["ought","shall","dare","must"],"answer_index":3,"stem_cn":"我想这个陌生人一定误解了我,于是又说了一遍名字。","explanation_cn":"对过去的肯定推测,填 must。✓ he must have misunderstood me. ✗ shall / ought(须加 to)/ dare:表推测“一定”用 must。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp3','choice','{"stem":"\"Someone ___ have built this reservoir while I was away.\"(must ___ 过去分词:对过去的推测,填这个助动词)","options":["must","would","must have","had"],"answer_index":2,"stem_cn":"我离开期间一定有人建了这座水库。","explanation_cn":"对过去的肯定推测 = must + have + 过去分词;此处需 must have + built。✓ Someone must have built this reservoir. ✗ must(缺 have)/ had / would:完整结构是 must have done。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp4','choice','{"stem":"\"I felt as if I ___ stumbled into a dream country.\"(as if + 过去完成,表与过去相反)","options":["was","had","have","would"],"answer_index":1,"stem_cn":"我觉得自己仿佛闯进了一个梦境之国。","explanation_cn":"as if + 过去完成,表与过去事实相反的比拟。✓ as if I had stumbled into a dream country. ✗ have / was / would:as if 表过去相反用 had done。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp4','choice','{"stem":"\"Everything looked as though it ___ been rearranged overnight.\"(as though + 过去完成)","options":["was","has","had","were"],"answer_index":2,"stem_cn":"一切看起来仿佛一夜之间被重新摆放过。","explanation_cn":"as though + 过去完成,表与过去相反的比拟。✓ as though it had been rearranged. ✗ has / was / were:此处用 had been。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp4','choice','{"stem":"\"He spoke as if he ___ known the valley all his life.\"(as if + 过去完成,表与过去相反)","options":["would","had","was","has"],"answer_index":1,"stem_cn":"他说起话来,仿佛一辈子都熟悉那座山谷。","explanation_cn":"as if + 过去完成,表与过去相反的比拟。✓ as if he had known the valley all his life. ✗ has / was / would:as if 表过去相反用 had done。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp5','choice','{"stem":"\"In the new land my father became ___ in his work and his plans.\"(be ___ in sth:全神贯注于,填过去分词)","options":["absorbs","absorb","absorbing","absorbed"],"answer_index":3,"stem_cn":"在新的国度,父亲一心扑在工作和计划上。","explanation_cn":"be absorbed in sth,“全神贯注于”;用过去分词 absorbed。✓ became absorbed in his work. ✗ absorbing(主动“吸引人的”)/ absorb / absorbs:此结构用 absorbed。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp5','choice','{"stem":"\"He asked me to make the journey on my ___.\"(on one''s ___:独自、靠自己,填这个词)","options":["single","alone","own","self"],"answer_index":2,"stem_cn":"他让我独自完成这趟旅程。","explanation_cn":"on one''s own,“独自、靠自己”;固定用 own。✓ on my own. ✗ self / alone / single:固定搭配是 on one''s own。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp5','choice','{"stem":"\"It was not that I remembered the road, ___ that my father had described it.\"(not that… ___ that…:不是因为…而是因为,填中间的连词)","options":["but","or","so","and"],"answer_index":0,"stem_cn":"并非我记得这条路,而是父亲曾描述过它。","explanation_cn":"not that… but that…,“不是因为…而是因为…”;固定用 but 连接。✓ not that I remembered…, but that my father had described it. ✗ and / so / or:固定结构是 not that…but that。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp6','choice','{"stem":"\"Something foreign and unfamiliar feels ___.\"(“异国的、陌生的”用哪个词)","options":["common","alien","native","modern"],"answer_index":1,"stem_cn":"陌生而不熟悉的感觉。","explanation_cn":"陌生而不熟悉、异国的是 alien。✓ everything seemed alien. ✗ native 本地的;✗ common 常见的;✗ modern 现代的——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp6','choice','{"stem":"\"A large man-made lake for storing water is a ___.\"(“水库”用哪个词)","options":["river","well","reservoir","harbor"],"answer_index":2,"stem_cn":"人工修建、用于蓄水的大湖。","explanation_cn":"人工修建、用于蓄水的大湖是 reservoir。✓ a man-made reservoir. ✗ river 河;✗ well 井;✗ harbor 港口——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',5,'am3_l57_gp6','choice','{"stem":"\"To go back over the same route is to ___ it.\"(“返回、重走”用哪个词)","options":["forget","retrace","mark","cross"],"answer_index":1,"stem_cn":"沿原路返回、重走。","explanation_cn":"沿原路返回、重走是 retrace。✓ retrace my route. ✗ forget 忘记;✗ cross 横过;✗ mark 标记——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"alien 的意思是:","options":["本地的","现代的","常见的","异国的,陌生的"],"answer_index":3,"explanation_cn":"alien = 异国的、陌生的。✓ everything seemed alien 一切都很陌生。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"emigrate 的意思是:","options":["移居国外","到达","停留","返回"],"answer_index":0,"explanation_cn":"emigrate = 移居国外。✓ he decided to emigrate 他决定移居国外。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"embedded 的意思是:","options":["松动的","临时的","扎牢的,嵌入的","漂浮的"],"answer_index":2,"explanation_cn":"embedded = 扎牢的、嵌入的。✓ firmly embedded in the new soil 深深扎在新土里。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"comprehensive 的意思是:","options":["全面的,详尽的","简短的","模糊的","错误的"],"answer_index":0,"explanation_cn":"comprehensive = 全面的、详尽的。✓ a comprehensive book of maps 详尽的地图册。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"horizon 的意思是:","options":["山谷","地平线","森林","港口"],"answer_index":1,"explanation_cn":"horizon = 地平线。✓ appeared on the horizon 出现在地平线上。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',6,NULL,'choice','{"stem":"reservoir 的意思是:","options":["喷泉","岛屿","水库","瀑布"],"answer_index":2,"explanation_cn":"reservoir = 水库。✓ a man-made reservoir 人工水库。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',7,NULL,'cloze','{"stem":"第 1 空","context":"I ___1___ expected to be near my objective, but everything still seemed alien. I looked at the odometer: I ___2___ come ten miles, yet there was only a lake where the village should be. I decided I must ___3___ taken a wrong turning, and I began to retrace my route. I felt as if I ___4___ stumbled into a dream country.","blank_no":1,"options":["had","have","was","did"],"answer_index":0,"explanation_cn":"had expected to do,过去原以为而未成。✓ I had expected to be near my objective."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',7,NULL,'cloze','{"stem":"第 2 空","context":"I ___1___ expected to be near my objective, but everything still seemed alien. I looked at the odometer: I ___2___ come ten miles, yet there was only a lake where the village should be. I decided I must ___3___ taken a wrong turning, and I began to retrace my route. I felt as if I ___4___ stumbled into a dream country.","blank_no":2,"options":["had","have","was","am"],"answer_index":0,"explanation_cn":"过去完成时,回溯更早的过去。✓ I had come ten miles."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',7,NULL,'cloze','{"stem":"第 3 空","context":"I ___1___ expected to be near my objective, but everything still seemed alien. I looked at the odometer: I ___2___ come ten miles, yet there was only a lake where the village should be. I decided I must ___3___ taken a wrong turning, and I began to retrace my route. I felt as if I ___4___ stumbled into a dream country.","blank_no":3,"options":["have","has","had","be"],"answer_index":0,"explanation_cn":"对过去的推测 must + have + 过去分词。✓ I must have taken a wrong turning."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',7,NULL,'cloze','{"stem":"第 4 空","context":"I ___1___ expected to be near my objective, but everything still seemed alien. I looked at the odometer: I ___2___ come ten miles, yet there was only a lake where the village should be. I decided I must ___3___ taken a wrong turning, and I began to retrace my route. I felt as if I ___4___ stumbled into a dream country.","blank_no":4,"options":["had","have","was","would"],"answer_index":0,"explanation_cn":"as if + 过去完成,与过去相反的比拟。✓ as if I had stumbled into a dream country."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',8,NULL,'choice','{"stem":"What had happened to the narrator''s old village?","options":["It had simply been abandoned","It had grown into a big city","It had burned down","It had been submerged under a man-made reservoir"],"answer_index":3,"explanation_cn":"录音说旧村已不复存在,因为整个山谷被淹,建成了一座人工水库。✓ submerged under a reservoir."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',8,NULL,'choice','{"stem":"Why was the narrator so sure he would recognize the way?","options":["His father had described every milestone to him","He had visited it recently","He had a perfect memory of the place","A friend was guiding him"],"answer_index":0,"explanation_cn":"录音说叙述者确信认得路,是因为父亲曾一遍遍描述每个路标处该看到什么。✓ father had described every milestone."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',8,NULL,'choice','{"stem":"Who finally told the narrator the truth about the village?","options":["His father","A man on horseback","A shopkeeper","A police officer"],"answer_index":1,"explanation_cn":"录音说是一个骑马路过的人告诉叙述者,村子已经没有了,并指向那片湖。✓ a man on horseback."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',9,NULL,'choice','{"stem":"你想说\"我回来时,村子早已消失在湖底\"(过去完成时):","options":["When I returned, the village had already disappeared under the lake.","When I returned, the village already disappeared under the lake.","When I returned, the village has already disappeared under the lake.","When I returned, the village had already disappear under the lake."],"answer_index":0,"explanation_cn":"过去完成时 had + 过去分词 disappeared,表在“我回来”之前已发生;不用 has、不用一般过去 disappeared、disappear 须用过去分词。✓ had already disappeared. 场合:回溯更早的过去。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',9,NULL,'choice','{"stem":"你想说\"我一定是在什么地方拐错了弯\"(对过去的推测):","options":["I must to have taken a wrong turning somewhere.","I must took a wrong turning somewhere.","I must have taken a wrong turning somewhere.","I must have took a wrong turning somewhere."],"answer_index":2,"explanation_cn":"对过去的推测 must + have + 过去分词 taken;不用 must took、不用 must to have、不用 must have took。✓ must have taken. 场合:根据迹象推断过去“一定…了”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',9,NULL,'choice','{"stem":"你想说\"我觉得自己仿佛闯进了一个梦境之国\"(as if + 过去完成):","options":["I felt as if I had stumble into a dream country.","I felt as if I had stumbled into a dream country.","I felt as if I stumbled into a dream country.","I felt as if I have stumbled into a dream country."],"answer_index":1,"explanation_cn":"as if + 过去完成 had stumbled,表与过去相反的比拟;不用 have、不用一般过去 stumbled、stumble 须用过去分词。✓ as if I had stumbled. 场合:说“仿佛(其实并没)…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"emigrate 的意思是:","options":["返回","移居国外","到达","停留"],"answer_index":1,"explanation_cn":"emigrate = 移居国外。✓ he decided to emigrate."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"horizon 的意思是:","options":["森林","港口","山谷","地平线"],"answer_index":3,"explanation_cn":"horizon = 地平线。✓ appeared on the horizon."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"\"When I returned, the village ___ already disappeared under the lake.\"(过去完成时,填助动词)","options":["would","had","has","was"],"answer_index":1,"stem_cn":"我回来时,村子早已消失在湖底。","explanation_cn":"过去完成时 had + 过去分词,回溯更早的过去。✓ the village had already disappeared. ✗ has / was / would。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"\"I felt as if I ___ stumbled into a dream country.\"(as if + 过去完成)","options":["have","was","would","had"],"answer_index":3,"stem_cn":"我觉得自己仿佛闯进了一个梦境之国。","explanation_cn":"as if + 过去完成 had + 过去分词,与过去相反的比拟。✓ as if I had stumbled. ✗ have / was / would。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"\"cool off\" 的意思是:","options":["加速","加热","冷却、降温","熄火"],"answer_index":2,"explanation_cn":"cool off = 冷却、降温。✓ let the car cool off."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"\"on one''s own\" 的意思是:","options":["独自、靠自己","按时","大声地","顺便"],"answer_index":0,"explanation_cn":"on one''s own = 独自、靠自己。✓ go on my own."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"Why did the narrator think he would not need the maps on the last stage?","options":["The road was clearly marked","He had traveled it many times","His father had described the route in detail","A guide was with him"],"answer_index":2,"passage":"I stopped to let the car cool off and to study the map. I had expected to be near my objective by now, but everything still seemed alien to me. I was only five when my father had taken me abroad, and that was eighteen years ago. He had decided to emigrate to build a better life for the two of us, and in the new land he became absorbed in his work and his plans. He always meant to go back one day, but only for a visit, never to stay — his roots and mine had become too firmly embedded in the new soil. Still, he longed to see the old folk again and to walk once more through the village where he was born. He fell ill a few months before we had planned to travel together, and when he knew he could not go, he made me promise to make the journey on my own. I hired a car the day after landing and bought a comprehensive book of maps, which I found most helpful on the cross-country journey, but which I had thought I would not need on the last stage. It was not that I actually remembered anything, but that my father had described, over and over, what I should see at every milestone after leaving the nearest town, so that I was positive I would recognize the place as familiar territory. Well, I had been wrong, for I was now lost. I looked at the map and then at the odometer. I had come ten miles since leaving the town, and at this point, according to my father, I should have been looking at farms and cottages in a valley, with the spire of the village church showing in the far distance. I could see no valley, no farms, no cottages and no spire — only a lake. I decided that I must have taken a wrong turning somewhere, so I drove back and began to retrace my route, taking frequent glances at the map. I landed up at the same corner. The strange thing was that the lake was not marked on the map at all. I felt as if I had stumbled into a dream country, where nothing was where it should be. As I sat wondering what to do, a man on horseback appeared on the horizon, riding in my direction. I waited until he came near and asked him the way to our old village. He told me, gently, that there was no longer any village. I thought he must have misunderstood me, so I repeated its name. This time he simply pointed to the lake. The village no longer existed, he said, because the whole valley had been submerged. The lake was not a natural one, but a man-made reservoir, and somewhere beneath its calm surface lay the home my father had never stopped dreaming of.","explanation_cn":"课文说叙述者以为最后一段用不上地图,是因为父亲曾一遍遍详细描述过沿途每个路标该看到什么。✓ father had described the route."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"What was strange about the lake?","options":["It was frozen even in summer","It was full of boats","It had no water in it","It was not marked on the map at all"],"answer_index":3,"passage":"I stopped to let the car cool off and to study the map. I had expected to be near my objective by now, but everything still seemed alien to me. I was only five when my father had taken me abroad, and that was eighteen years ago. He had decided to emigrate to build a better life for the two of us, and in the new land he became absorbed in his work and his plans. He always meant to go back one day, but only for a visit, never to stay — his roots and mine had become too firmly embedded in the new soil. Still, he longed to see the old folk again and to walk once more through the village where he was born. He fell ill a few months before we had planned to travel together, and when he knew he could not go, he made me promise to make the journey on my own. I hired a car the day after landing and bought a comprehensive book of maps, which I found most helpful on the cross-country journey, but which I had thought I would not need on the last stage. It was not that I actually remembered anything, but that my father had described, over and over, what I should see at every milestone after leaving the nearest town, so that I was positive I would recognize the place as familiar territory. Well, I had been wrong, for I was now lost. I looked at the map and then at the odometer. I had come ten miles since leaving the town, and at this point, according to my father, I should have been looking at farms and cottages in a valley, with the spire of the village church showing in the far distance. I could see no valley, no farms, no cottages and no spire — only a lake. I decided that I must have taken a wrong turning somewhere, so I drove back and began to retrace my route, taking frequent glances at the map. I landed up at the same corner. The strange thing was that the lake was not marked on the map at all. I felt as if I had stumbled into a dream country, where nothing was where it should be. As I sat wondering what to do, a man on horseback appeared on the horizon, riding in my direction. I waited until he came near and asked him the way to our old village. He told me, gently, that there was no longer any village. I thought he must have misunderstood me, so I repeated its name. This time he simply pointed to the lake. The village no longer existed, he said, because the whole valley had been submerged. The lake was not a natural one, but a man-made reservoir, and somewhere beneath its calm surface lay the home my father had never stopped dreaming of.","explanation_cn":"课文说奇怪的是那片湖在地图上根本没有标出。✓ not marked on the map."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"What had covered the old valley and village?","options":["A new highway","A man-made reservoir","A desert","A thick forest"],"answer_index":1,"audio":"I stopped to let the car cool off and to study the map. I had expected to be near my objective by now, but everything still seemed alien to me. I was only five when my father had taken me abroad, and that was eighteen years ago. He had decided to emigrate to build a better life for the two of us, and in the new land he became absorbed in his work and his plans. He always meant to go back one day, but only for a visit, never to stay — his roots and mine had become too firmly embedded in the new soil. Still, he longed to see the old folk again and to walk once more through the village where he was born. He fell ill a few months before we had planned to travel together, and when he knew he could not go, he made me promise to make the journey on my own. I hired a car the day after landing and bought a comprehensive book of maps, which I found most helpful on the cross-country journey, but which I had thought I would not need on the last stage. It was not that I actually remembered anything, but that my father had described, over and over, what I should see at every milestone after leaving the nearest town, so that I was positive I would recognize the place as familiar territory. Well, I had been wrong, for I was now lost. I looked at the map and then at the odometer. I had come ten miles since leaving the town, and at this point, according to my father, I should have been looking at farms and cottages in a valley, with the spire of the village church showing in the far distance. I could see no valley, no farms, no cottages and no spire — only a lake. I decided that I must have taken a wrong turning somewhere, so I drove back and began to retrace my route, taking frequent glances at the map. I landed up at the same corner. The strange thing was that the lake was not marked on the map at all. I felt as if I had stumbled into a dream country, where nothing was where it should be. As I sat wondering what to do, a man on horseback appeared on the horizon, riding in my direction. I waited until he came near and asked him the way to our old village. He told me, gently, that there was no longer any village. I thought he must have misunderstood me, so I repeated its name. This time he simply pointed to the lake. The village no longer existed, he said, because the whole valley had been submerged. The lake was not a natural one, but a man-made reservoir, and somewhere beneath its calm surface lay the home my father had never stopped dreaming of.","explanation_cn":"课文说整个山谷和村子都被淹没在一座人工水库之下。✓ a man-made reservoir."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l57',10,NULL,'choice','{"stem":"How did the man on horseback show the narrator what had happened?","options":["He pointed to the lake","He drew a map","He led him to the town","He gave him a letter"],"answer_index":0,"audio":"I stopped to let the car cool off and to study the map. I had expected to be near my objective by now, but everything still seemed alien to me. I was only five when my father had taken me abroad, and that was eighteen years ago. He had decided to emigrate to build a better life for the two of us, and in the new land he became absorbed in his work and his plans. He always meant to go back one day, but only for a visit, never to stay — his roots and mine had become too firmly embedded in the new soil. Still, he longed to see the old folk again and to walk once more through the village where he was born. He fell ill a few months before we had planned to travel together, and when he knew he could not go, he made me promise to make the journey on my own. I hired a car the day after landing and bought a comprehensive book of maps, which I found most helpful on the cross-country journey, but which I had thought I would not need on the last stage. It was not that I actually remembered anything, but that my father had described, over and over, what I should see at every milestone after leaving the nearest town, so that I was positive I would recognize the place as familiar territory. Well, I had been wrong, for I was now lost. I looked at the map and then at the odometer. I had come ten miles since leaving the town, and at this point, according to my father, I should have been looking at farms and cottages in a valley, with the spire of the village church showing in the far distance. I could see no valley, no farms, no cottages and no spire — only a lake. I decided that I must have taken a wrong turning somewhere, so I drove back and began to retrace my route, taking frequent glances at the map. I landed up at the same corner. The strange thing was that the lake was not marked on the map at all. I felt as if I had stumbled into a dream country, where nothing was where it should be. As I sat wondering what to do, a man on horseback appeared on the horizon, riding in my direction. I waited until he came near and asked him the way to our old village. He told me, gently, that there was no longer any village. I thought he must have misunderstood me, so I repeated its name. This time he simply pointed to the lake. The village no longer existed, he said, because the whole valley had been submerged. The lake was not a natural one, but a man-made reservoir, and somewhere beneath its calm surface lay the home my father had never stopped dreaming of.","explanation_cn":"课文说当叙述者又说了一遍村名,那人只是指了指那片湖。✓ pointed to the lake."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l58',3,12,58,'A Spot of Bother','一点儿小麻烦','独立主格结构(名词 + 分词/形容词作状语)、现在分词短语作方式/伴随状语、it 作形式主语 + 不定式、情态动词 + 完成式(must have done 对过去推测 / should have done 本该做而未做)、with 复合结构/either…or/短语动词(NCE3 第三册 Unit 3 无 KS 页,考点由课文结构 + Notes on the text 自取;原创承载·老太太回家发现公寓被窃贼翻箱倒柜洗劫、报警找楼管的冷幽默悬疑·窃贼已逃无对峙无暴力;美语化 apartment/elevator/jewelry/master key)','老太太回到自己居住的公寓楼,心里很高兴。去店里买东西把她累坏了,回家路上每走一步,手里的袋子就更沉一点。在电梯里,她一心想着午饭和好好歇一歇;可当她在自家那层走出电梯,这两件事全被忘到脑后——她突然发现自家大门开着。她本想着第二天上午一定要好好说说那个钟点工,竟这么粗心大意;转念却记起,自己是钟点工走后才去买东西的,而且两把锁都是她亲手拧上的。她慢慢走进门厅,一眼就看见所有房门都敞着——可按照惯例,她出门前明明把它们都关好了。朝起居室望去,她看见写字台那边一片狼藉。事情十分清楚:她不在时,有窃贼闯了进来。她的第一反应是挨个房间去找那入侵者,但又觉得以自己这年纪,有人陪着也许更稳妥,于是下楼去地下室把楼管请了上来。这时她两腿已开始发抖,便坐下喝了一杯很浓的茶,楼管则给警察打了电话。镇定重新恢复后,她准备好和楼管一起动身,去搜查公寓里可能还潜藏着的人。他俩逐屋查看,小心翼翼不碰任何东西,生怕妨碍警察寻找指纹。屋里的混乱几乎叫人难以想象。她在这套公寓里住了三十年,又特别爱收藏东西;看上去她所有的家当都被翻了出来,里里外外倒腾了个遍。至少,她想,那些几年前就该扔掉的东西,如今倒省事了。随后一位巡官带着一名警员赶到,她讲了自己如何发现被洗劫的公寓。巡官开始找指纹,警员则查看大门锁并未被撬——由此证明,窃贼要么用了万能钥匙,要么是翻阳台进来的。指纹一无所获,巡官却发现一个脏兮兮的红布包,里头装着珠宝,老太太说那不是她的。看来这套公寓并不是窃贼当天下手的第一家,他一定是被惊扰了。巡官劝她这几夜别独自住,老太太觉得他大惊小怪,但既然楼管也附和,她便打电话给女儿求援,说自己碰上了一点儿小麻烦。','{"q":"Listen and answer — What did the old lady find when she got home?","options":["Her apartment had been broken into","A surprise party","A water leak","Nothing unusual"],"answer_index":0}'::jsonb,'{"title":"独立主格 / 现在分词作状语 / it 形式主语 / 情态 + 完成式","intro":"①独立主格:名词(代词)+ 分词/形容词,作状语,有自己的逻辑主语:Her composure regained, she was ready…。②现在分词短语作方式/伴随状语,逻辑主语与主句一致:Looking into the room, she saw…;being careful to touch nothing。③it 作形式主语,真正主语是后面的不定式:It might be more prudent to have someone with her。④情态 + have + 过去分词:must have done(对过去推测“一定…了”)/ should have done(过去本该做而没做)。","table":{"headers":["用法","结构","例子"],"rows":[["独立主格","名词 + 分词/形容词","Her composure regained, she…"],["现在分词作状语","doing …, 主句","Looking into the room, she saw…"],["it 形式主语","It is/might be … to do","It might be prudent to have help"],["情态 + 完成式","must/should + have + 过去分词","must have been disturbed"]]},"specialRules":[{"rule":"独立主格有自己的逻辑主语(Her composure regained),不同于普通分词状语(逻辑主语=主句主语)。","mark":"Her composure regained, she…"},{"rule":"must have done=对过去的肯定推测;should have done=过去本该做却没做,含责备/惋惜。","mark":"must have done / should have done"},{"rule":"美式用词:apartment(公寓,英式 flat)、elevator(电梯,英式 lift)、jewelry(珠宝,英式 jewellery)。本课已按美语写。","mark":"apartment / elevator / jewelry"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l58',1,NULL,'The old lady was glad to be back at the apartment building where she lived. Her shopping had tired her, and her bag had grown heavier with every step of the way home. In the elevator her thoughts were on lunch and a good rest; but when she stepped out at her own floor, both were forgotten in her sudden discovery that her front door stood open.','老太太回到自己居住的公寓楼,心里很高兴。去店里买东西把她累坏了,回家路上每走一步,手里的袋子就更沉一点。在电梯里,她一心想着午饭和好好歇一歇;可当她在自家那层走出电梯,这两件事全被忘到脑后——她突然发现自家大门开着。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l58',2,NULL,'She was thinking that she must reprimand her cleaning lady the next morning for such a careless piece of negligence, when she remembered that she had gone shopping after the cleaning lady had left, and she knew that she had turned both keys in their locks herself. She walked slowly into the hall and at once noticed that all the room doors were open, yet, following her regular habit, she had shut them before going out.','她本想着第二天上午一定要好好说说那个钟点工,竟这么粗心大意;转念却记起,自己是钟点工走后才去买东西的,而且两把锁都是她亲手拧上的。她慢慢走进门厅,一眼就看见所有房门都敞着——可按照惯例,她出门前明明把它们都关好了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l58',3,NULL,'Looking into the living room, she saw a scene of confusion over by her writing desk. It was as clear as daylight then that a burglar had forced an entry while she was away. Her first impulse was to go from room to room in search of the intruder, but she decided that, at her age, it might be more prudent to have someone with her. So she went down to fetch the building manager from the basement.','朝起居室望去,她看见写字台那边一片狼藉。事情十分清楚:她不在时,有窃贼闯了进来。她的第一反应是挨个房间去找那入侵者,但又觉得以自己这年纪,有人陪着也许更稳妥,于是下楼去把楼管请了上来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l58',4,NULL,'By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea while he called the police. Then, her composure regained, she was ready to set off with the manager''s help to look for anyone who might still be lurking in her apartment. They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints. The chaos was almost inconceivable.','这时她两腿已开始发抖,便坐下喝了一杯很浓的茶,楼管则给警察打了电话。镇定重新恢复后,她准备好和楼管一起动身,去搜查公寓里可能还潜藏着的人。他俩逐屋查看,小心翼翼不碰任何东西,生怕妨碍警察寻找指纹。屋里的混乱几乎叫人难以想象。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l58',5,NULL,'At least, she thought, sorting out the things she should have discarded years ago was now being made easier for her. Then a police inspector arrived and checked the front-door locks, which had not been forced, proving that the burglar had either used a master key or climbed in over the balcony. The inspector found a red bundle of jewelry that was not hers, so this apartment was apparently not the burglar''s first stop, and he must have been disturbed. The old lady called her daughter and asked for her help with what she called a little spot of bother.','至少,她想,那些几年前就该扔掉的东西,如今倒省事了。随后巡官赶到,查看大门锁并未被撬——由此证明窃贼要么用了万能钥匙,要么翻阳台进来。巡官发现一个装着珠宝的红布包,老太太说那不是她的;看来这套公寓并不是窃贼下手的第一家,他一定是被惊扰了。老太太便打电话给女儿求援,说自己碰上了一点儿小麻烦。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
