INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l58','set off','',NULL,'/set ɔːf/','She was ready to set off to search the apartment.','她准备好动身去搜查公寓。','We set off at dawn.','我们黎明时动身。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l58','sort out','',NULL,'/sɔːrt aʊt/','Sorting out the old things was made easier for her.','整理那些旧东西对她来说省事多了。','He sorted out the papers on his desk.','他整理了桌上的文件。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l58','go through','',NULL,'/ɡoʊ θruː/','They went through the rooms carefully.','他们仔细查看了每个房间。','The police went through her statement again.','警察又核了一遍她的陈述。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l58','as clear as daylight','',NULL,'/əz klɪr əz ˈdeɪlaɪt/','It was as clear as daylight that a burglar had broken in.','有窃贼闯入这一点十分清楚。','Her meaning was as clear as daylight.','她的意思一清二楚。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp1','choice','{"stem":"\"Her composure ___, she was ready to search the apartment.\"(独立主格:名词 + 过去分词,作状语)","options":["to regain","regain","regaining","regained"],"answer_index":3,"stem_cn":"镇定重新恢复后,她准备好去搜查公寓。","explanation_cn":"独立主格:名词 composure + 过去分词 regained(被动“被重新恢复”),作状语,有自己的逻辑主语。✓ Her composure regained, she was ready… ✗ regaining(主动)/ regain / to regain:此处表被动用过去分词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp1','choice','{"stem":"\"Her legs ___ to tremble, the old lady sat down for tea.\"(独立主格:名词 + 现在分词)","options":["begin","began","beginning","begun"],"answer_index":2,"stem_cn":"双腿开始发抖,老太太便坐下喝茶。","explanation_cn":"独立主格:名词 legs + 现在分词 beginning(主动“开始…”),作状语。✓ Her legs beginning to tremble, she sat down. ✗ begun / began / begin:表主动进行用现在分词 beginning。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp1','choice','{"stem":"\"The tea ___, she felt calm enough to begin.\"(独立主格:名词 + 过去分词,作时间状语)","options":["finishing","finish","to finish","finished"],"answer_index":3,"stem_cn":"茶喝完后,她觉得镇定得可以开始了。","explanation_cn":"独立主格:名词 tea + 过去分词 finished(“茶喝完后”),作时间状语。✓ The tea finished, she felt calm. ✗ finishing / finish / to finish:表完成用过去分词 finished。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp2','choice','{"stem":"\"___ into the living room, she saw a scene of confusion.\"(现在分词短语作状语,主动“朝…看”)","options":["Looking","Look","To look","Looked"],"answer_index":0,"stem_cn":"朝起居室望去,她看见一片狼藉。","explanation_cn":"现在分词短语作状语,逻辑主语=主句的 she,主动“朝…看”。✓ Looking into the living room, she saw… ✗ Looked(被动/一般过去)/ Look / To look:主动伴随用 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp2','choice','{"stem":"\"They went through the rooms, ___ careful to touch nothing.\"(现在分词短语作方式状语)","options":["be","to be","been","being"],"answer_index":3,"stem_cn":"他们逐屋查看,小心翼翼不碰任何东西。","explanation_cn":"现在分词短语作方式状语,being careful to touch nothing。✓ They went through the rooms, being careful… ✗ been / be / to be:此处用现在分词 being。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp2','choice','{"stem":"\"___ her regular habit, she had shut all the doors before going out.\"(现在分词短语作状语,“按照…”)","options":["Follow","Following","To follow","Followed"],"answer_index":1,"stem_cn":"按照惯例,她出门前已把所有门关上。","explanation_cn":"现在分词短语作状语,“按照…”,逻辑主语=she。✓ Following her regular habit, she had shut the doors. ✗ Followed / Follow / To follow:主动用现在分词 Following。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp3','choice','{"stem":"\"At her age, ___ might be more prudent to have someone with her.\"(形式主语,填代词)","options":["that","there","this","it"],"answer_index":3,"stem_cn":"以她的年纪,有人陪着也许更稳妥。","explanation_cn":"it 作形式主语,真正的主语是后面的不定式 to have someone with her。✓ it might be more prudent to have someone with her. ✗ that / this / there:形式主语用 it。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp3','choice','{"stem":"\"It might be more prudent ___ have someone with her.\"(形式主语句:真正主语是后面的不定式,填不定式符号)","options":["to","for","of","with"],"answer_index":0,"stem_cn":"有人陪着她也许更稳妥。","explanation_cn":"形式主语句 it + be + 形容词 + to do,真正主语是不定式,填不定式符号 to。✓ It might be more prudent to have someone with her. ✗ for / of / with:此处用 to have。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp3','choice','{"stem":"\"It seemed almost impossible ___ find a single fingerprint.\"(it 形式主语 + 不定式)","options":["for","that","in","to"],"answer_index":3,"stem_cn":"似乎几乎不可能找到一枚指纹。","explanation_cn":"it 作形式主语,真正主语是不定式 to find…。✓ It seemed almost impossible to find a single fingerprint. ✗ that / for / in:此处用 to find。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp4','choice','{"stem":"\"The burglar ___ have been disturbed, for he left the jewelry behind.\"(对过去的推测“一定…了”)","options":["would","must","can","need"],"answer_index":1,"stem_cn":"窃贼一定是被惊扰了,所以丢下了珠宝。","explanation_cn":"对过去的肯定推测“一定…了”用 must + have + 过去分词。✓ The burglar must have been disturbed. ✗ can / would / need:表肯定推测用 must。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp4','choice','{"stem":"\"She ___ have discarded those old things years ago.\"(过去本该做而没做:用情态词 + have + 过去分词,填这个情态词)","options":["can","must","should","would"],"answer_index":2,"stem_cn":"那些旧东西她几年前就该扔掉。","explanation_cn":"过去本该做而没做用 should + have + 过去分词,含惋惜/责备。✓ She should have discarded those things years ago. ✗ must(表推测)/ can / would:表“本该”用 should。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp4','choice','{"stem":"\"The burglar must ___ used a master key to get in.\"(must ___ 过去分词:对过去的推测,填这个助动词)","options":["have","having","has","had"],"answer_index":0,"stem_cn":"窃贼一定是用万能钥匙进来的。","explanation_cn":"must + have + 过去分词构成对过去的推测;此处填助动词 have。✓ must have used a master key. ✗ has / had / having:must 后一律用 have + 过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp5','choice','{"stem":"\"Her bag grew heavier ___ every step of the way home.\"(随…而变化:填引出伴随状语的介词)","options":["by","with","of","on"],"answer_index":1,"stem_cn":"回家路上每走一步,她的包就更沉一点。","explanation_cn":"with + 名词短语作状语,表“随…而(变化)”。✓ heavier with every step. ✗ by / on / of:表伴随变化用 with。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp5','choice','{"stem":"\"The burglar had ___ used a master key or climbed over the balcony.\"(要么…要么…:填与 or 搭配的前一个词)","options":["both","neither","either","whether"],"answer_index":2,"stem_cn":"窃贼要么用了万能钥匙,要么翻阳台进来。","explanation_cn":"either… or… “要么…要么…”;与 or 搭配的前一个词是 either。✓ either used a master key or climbed over the balcony. ✗ both / neither / whether:与 or 搭配用 either。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp5','choice','{"stem":"\"She was ready to set ___ with the manager to search the flat.\"(set ___:动身、出发,填副词)","options":["down","up","in","off"],"answer_index":3,"stem_cn":"她准备好动身,和经理一起去搜查。","explanation_cn":"set off,“动身、出发”;固定用副词 off。✓ ready to set off with the manager. ✗ in / up / down:固定搭配是 set off。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp6','choice','{"stem":"\"A careless failure to take proper care is ___.\"(“粗心大意”用哪个词)","options":["courage","wisdom","negligence","patience"],"answer_index":2,"stem_cn":"因疏忽而未尽应有的小心。","explanation_cn":"因疏忽而未尽应有的小心是 negligence。✓ such a careless piece of negligence. ✗ patience 耐心;✗ courage 勇气;✗ wisdom 智慧——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp6','choice','{"stem":"\"To rob a place, leaving it in wild disorder, is to ___ it.\"(“洗劫”用哪个词)","options":["ransack","repair","decorate","guard"],"answer_index":0,"stem_cn":"把一处地方翻箱倒柜洗劫一空。","explanation_cn":"把一处地方翻箱倒柜洗劫一空是 ransack。✓ the ransacked apartment. ✗ decorate 装饰;✗ repair 修理;✗ guard 守卫——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',5,'am3_l58_gp6','choice','{"stem":"\"To hide and wait, ready to do harm, is to ___.\"(“潜藏”用哪个词)","options":["rest","travel","sing","lurk"],"answer_index":3,"stem_cn":"潜伏等待、伺机作案。","explanation_cn":"潜伏等待、伺机作案是 lurk。✓ anyone who might still be lurking. ✗ sing 唱;✗ rest 休息;✗ travel 旅行——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"negligence 的意思是:","options":["粗心大意,疏忽","智慧","勇气","耐心"],"answer_index":0,"explanation_cn":"negligence = 粗心大意、疏忽。✓ a careless piece of negligence 粗心大意。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"prudent 的意思是:","options":["鲁莽的","懒惰的","谨慎的","慷慨的"],"answer_index":2,"explanation_cn":"prudent = 谨慎的。✓ more prudent to have someone with her 有人陪着更稳妥。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"composure 的意思是:","options":["疲惫","愤怒","惊慌","镇静,沉着"],"answer_index":3,"explanation_cn":"composure = 镇静、沉着。✓ her composure regained 镇定恢复后。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"intruder 的意思是:","options":["入侵者","房主","邻居","客人"],"answer_index":0,"explanation_cn":"intruder = 入侵者。✓ in search of the intruder 搜寻入侵者。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"chaos 的意思是:","options":["宁静","秩序","整洁","混乱,无秩序"],"answer_index":3,"explanation_cn":"chaos = 混乱、无秩序。✓ the chaos was almost inconceivable 一片难以想象的混乱。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',6,NULL,'choice','{"stem":"ransack 的意思是:","options":["装饰","打扫","洗劫,翻找","修理"],"answer_index":2,"explanation_cn":"ransack = 洗劫、翻找。✓ the ransacked apartment 被洗劫的公寓。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',7,NULL,'cloze','{"stem":"第 1 空","context":"The old lady found her front door open. ___1___ into the living room, she saw a scene of confusion. It was as clear as daylight that a burglar ___2___ forced an entry. At her age, it might be more prudent ___3___ have someone with her. The burglar ___4___ have been disturbed, for he left the jewelry behind.","blank_no":1,"options":["Looking","Looked","Look","To look"],"answer_index":0,"explanation_cn":"现在分词短语作状语,主动“朝…看”。✓ Looking into the living room, she saw…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',7,NULL,'cloze','{"stem":"第 2 空","context":"The old lady found her front door open. ___1___ into the living room, she saw a scene of confusion. It was as clear as daylight that a burglar ___2___ forced an entry. At her age, it might be more prudent ___3___ have someone with her. The burglar ___4___ have been disturbed, for he left the jewelry behind.","blank_no":2,"options":["had","has","was","would"],"answer_index":0,"explanation_cn":"过去完成时,burglar had forced an entry,比“她发现”更早发生。✓ a burglar had forced an entry."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',7,NULL,'cloze','{"stem":"第 3 空","context":"The old lady found her front door open. ___1___ into the living room, she saw a scene of confusion. It was as clear as daylight that a burglar ___2___ forced an entry. At her age, it might be more prudent ___3___ have someone with her. The burglar ___4___ have been disturbed, for he left the jewelry behind.","blank_no":3,"options":["to","for","of","with"],"answer_index":0,"explanation_cn":"it 形式主语,真正主语是不定式 to have…,填 to。✓ more prudent to have someone with her."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',7,NULL,'cloze','{"stem":"第 4 空","context":"The old lady found her front door open. ___1___ into the living room, she saw a scene of confusion. It was as clear as daylight that a burglar ___2___ forced an entry. At her age, it might be more prudent ___3___ have someone with her. The burglar ___4___ have been disturbed, for he left the jewelry behind.","blank_no":4,"options":["must","can","would","need"],"answer_index":0,"explanation_cn":"对过去的肯定推测,must + have + 过去分词。✓ The burglar must have been disturbed."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',8,NULL,'choice','{"stem":"What did the old lady find when she got home?","options":["Her apartment had been broken into and ransacked","A party in progress","A leak in the ceiling","Her keys were missing"],"answer_index":0,"explanation_cn":"录音说老太太回家发现大门开着、屋里一片狼藉,窃贼闯入把公寓翻了个遍。✓ broken into and ransacked."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',8,NULL,'choice','{"stem":"Why did she fetch the building manager before searching?","options":["He had the only spare key","He was a retired police officer","She could not open the door","She thought it more prudent, at her age, to have company"],"answer_index":3,"explanation_cn":"录音说她本想自己挨屋去找,但觉得以自己的年纪,有人陪着更稳妥,便去请了楼管。✓ more prudent to have company."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',8,NULL,'choice','{"stem":"What strange thing did the inspector find?","options":["Muddy footprints on the balcony","A broken window","A red bundle of jewelry that was not hers","A note from the burglar"],"answer_index":2,"explanation_cn":"录音说巡官发现一个脏红布包,里头装着珠宝,老太太说那不是她的——说明窃贼当天先劫过别处。✓ a red bundle of jewelry."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',9,NULL,'choice','{"stem":"你想说\"朝起居室望去,她看见一片狼藉\"(现在分词作状语):","options":["Looked into the living room, she saw a scene of confusion.","To look into the living room, she saw a scene of confusion.","Look into the living room, she saw a scene of confusion.","Looking into the living room, she saw a scene of confusion."],"answer_index":3,"explanation_cn":"现在分词短语作状语用主动 Looking;不用 Looked、不用原形 Look、不用 To look。✓ Looking into…, she saw… 场合:表达“…时,她…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',9,NULL,'choice','{"stem":"你想说\"窃贼一定是被惊扰了\"(对过去的推测):","options":["The burglar must was disturbed.","The burglar must have been disturbed.","The burglar must to have been disturbed.","The burglar must have been disturb."],"answer_index":1,"explanation_cn":"对过去的推测 must + have + been + 过去分词 disturbed;不用 must was、不用 must to have、disturb 须用过去分词。✓ must have been disturbed. 场合:根据迹象推断过去“一定…了”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',9,NULL,'choice','{"stem":"你想说\"镇定重新恢复后,她准备好去搜查公寓\"(独立主格):","options":["Her composure regaining, she was ready to search the apartment.","Her composure was regained, she was ready to search the apartment.","Her composure regained, she was ready to search the apartment.","Her composure regain, she was ready to search the apartment."],"answer_index":2,"explanation_cn":"独立主格:名词 composure + 过去分词 regained(被动),自带动作对象;不用 regaining(主动)、不加 was、不用原形 regain。✓ Her composure regained, she… 场合:表“…之后,她…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"prudent 的意思是:","options":["慷慨的","鲁莽的","谨慎的","懒惰的"],"answer_index":2,"explanation_cn":"prudent = 谨慎的。✓ more prudent to have someone with her."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"composure 的意思是:","options":["惊慌","镇静,沉着","愤怒","疲惫"],"answer_index":1,"explanation_cn":"composure = 镇静、沉着。✓ her composure regained."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"\"___ into the living room, she saw a scene of confusion.\"(现在分词短语作状语,主动)","options":["Looked","Look","To look","Looking"],"answer_index":3,"stem_cn":"朝起居室望去,她看见一片狼藉。","explanation_cn":"现在分词短语作状语,主动“朝…看”。✓ Looking into the living room, she saw… ✗ Looked / Look / To look。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"\"The burglar ___ have been disturbed, for he left the jewelry behind.\"(对过去的推测“一定…了”)","options":["can","would","must","need"],"answer_index":2,"stem_cn":"窃贼一定是被惊扰了。","explanation_cn":"对过去的肯定推测“一定…了”,must + have + 过去分词。✓ The burglar must have been disturbed. ✗ can / would / need。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"\"set off\" 的意思是:","options":["动身、出发","取消","归还","修理"],"answer_index":0,"explanation_cn":"set off = 动身、出发。✓ ready to set off with the manager."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"\"sort out\" 的意思是:","options":["弄丢","整理、清理","藏起来","弄脏"],"answer_index":1,"explanation_cn":"sort out = 整理、清理。✓ sorting out the old things."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"How did the old lady know she herself had not left the doors open?","options":["The police confirmed it","She never used those doors","She had turned both keys in the locks after the cleaning lady left","The manager told her so"],"answer_index":2,"passage":"The old lady was glad to be back at the apartment building where she lived. Her shopping had tired her, and her bag had grown heavier with every step of the way home. In the elevator her thoughts were on lunch and a good rest; but when she stepped out at her own floor, both were forgotten in her sudden discovery that her front door stood open. She was thinking that she must reprimand her cleaning lady the next morning for such a careless piece of negligence, when she remembered that she had gone shopping after the cleaning lady had left, and she knew that she had turned both keys in their locks herself. She walked slowly into the hall and at once noticed that all the room doors were open, yet, following her regular habit, she had shut them before going out. Looking into the living room, she saw a scene of confusion over by her writing desk. It was as clear as daylight then that a burglar had forced an entry while she was away. Her first impulse was to go from room to room in search of the intruder, but she decided that, at her age, it might be more prudent to have someone with her. So she went down to fetch the building manager from the basement. By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea while he called the police. Then, her composure regained, she was ready to set off with the manager''s help to look for anyone who might still be lurking in her apartment. They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints. The chaos was almost inconceivable. She had lived in the apartment for thirty years and loved to collect and keep things; and it seemed as though everything she owned had been pulled out and turned over and over. At least, she thought, sorting out the things she should have discarded years ago was now being made easier for her. Then a police inspector arrived with an officer, and she told them how she had found the ransacked apartment. The inspector began to look for fingerprints, while the officer checked that the front-door locks had not been forced, thereby proving that the burglar had either used a master key or climbed in over the balcony. There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewelry the old lady said was not hers. So this apartment was apparently not the burglar''s first stop that day, and he must have been disturbed. The inspector advised her not to stay alone for a few nights. The old lady thought he was a fussy creature, but since the manager agreed with him, she called her daughter and asked for her help with what she called a little spot of bother.","explanation_cn":"课文说她记起自己是钟点工走后才去买东西的,而且两把锁都是她亲手拧上的,所以门不是自己忘关的。✓ turned both keys herself."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"Why did the police think the burglar had used a master key or the balcony?","options":["A key was found on the floor","The front-door locks had not been forced","A neighbor saw him climb","The balcony door was broken"],"answer_index":1,"passage":"The old lady was glad to be back at the apartment building where she lived. Her shopping had tired her, and her bag had grown heavier with every step of the way home. In the elevator her thoughts were on lunch and a good rest; but when she stepped out at her own floor, both were forgotten in her sudden discovery that her front door stood open. She was thinking that she must reprimand her cleaning lady the next morning for such a careless piece of negligence, when she remembered that she had gone shopping after the cleaning lady had left, and she knew that she had turned both keys in their locks herself. She walked slowly into the hall and at once noticed that all the room doors were open, yet, following her regular habit, she had shut them before going out. Looking into the living room, she saw a scene of confusion over by her writing desk. It was as clear as daylight then that a burglar had forced an entry while she was away. Her first impulse was to go from room to room in search of the intruder, but she decided that, at her age, it might be more prudent to have someone with her. So she went down to fetch the building manager from the basement. By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea while he called the police. Then, her composure regained, she was ready to set off with the manager''s help to look for anyone who might still be lurking in her apartment. They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints. The chaos was almost inconceivable. She had lived in the apartment for thirty years and loved to collect and keep things; and it seemed as though everything she owned had been pulled out and turned over and over. At least, she thought, sorting out the things she should have discarded years ago was now being made easier for her. Then a police inspector arrived with an officer, and she told them how she had found the ransacked apartment. The inspector began to look for fingerprints, while the officer checked that the front-door locks had not been forced, thereby proving that the burglar had either used a master key or climbed in over the balcony. There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewelry the old lady said was not hers. So this apartment was apparently not the burglar''s first stop that day, and he must have been disturbed. The inspector advised her not to stay alone for a few nights. The old lady thought he was a fussy creature, but since the manager agreed with him, she called her daughter and asked for her help with what she called a little spot of bother.","explanation_cn":"课文说警员查看大门锁并未被撬,由此推断窃贼要么用万能钥匙,要么翻阳台进来。✓ locks had not been forced."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"Who did the old lady finally call for help?","options":["A locksmith","Her doctor","Her daughter","A taxi"],"answer_index":2,"audio":"The old lady was glad to be back at the apartment building where she lived. Her shopping had tired her, and her bag had grown heavier with every step of the way home. In the elevator her thoughts were on lunch and a good rest; but when she stepped out at her own floor, both were forgotten in her sudden discovery that her front door stood open. She was thinking that she must reprimand her cleaning lady the next morning for such a careless piece of negligence, when she remembered that she had gone shopping after the cleaning lady had left, and she knew that she had turned both keys in their locks herself. She walked slowly into the hall and at once noticed that all the room doors were open, yet, following her regular habit, she had shut them before going out. Looking into the living room, she saw a scene of confusion over by her writing desk. It was as clear as daylight then that a burglar had forced an entry while she was away. Her first impulse was to go from room to room in search of the intruder, but she decided that, at her age, it might be more prudent to have someone with her. So she went down to fetch the building manager from the basement. By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea while he called the police. Then, her composure regained, she was ready to set off with the manager''s help to look for anyone who might still be lurking in her apartment. They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints. The chaos was almost inconceivable. She had lived in the apartment for thirty years and loved to collect and keep things; and it seemed as though everything she owned had been pulled out and turned over and over. At least, she thought, sorting out the things she should have discarded years ago was now being made easier for her. Then a police inspector arrived with an officer, and she told them how she had found the ransacked apartment. The inspector began to look for fingerprints, while the officer checked that the front-door locks had not been forced, thereby proving that the burglar had either used a master key or climbed in over the balcony. There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewelry the old lady said was not hers. So this apartment was apparently not the burglar''s first stop that day, and he must have been disturbed. The inspector advised her not to stay alone for a few nights. The old lady thought he was a fussy creature, but since the manager agreed with him, she called her daughter and asked for her help with what she called a little spot of bother.","explanation_cn":"课文说老太太最后打电话向女儿求援,请她帮忙。✓ called her daughter."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l58',10,NULL,'choice','{"stem":"What did the old lady understatedly call the whole event?","options":["A little spot of bother","A great adventure","A total disaster","A stroke of luck"],"answer_index":0,"audio":"The old lady was glad to be back at the apartment building where she lived. Her shopping had tired her, and her bag had grown heavier with every step of the way home. In the elevator her thoughts were on lunch and a good rest; but when she stepped out at her own floor, both were forgotten in her sudden discovery that her front door stood open. She was thinking that she must reprimand her cleaning lady the next morning for such a careless piece of negligence, when she remembered that she had gone shopping after the cleaning lady had left, and she knew that she had turned both keys in their locks herself. She walked slowly into the hall and at once noticed that all the room doors were open, yet, following her regular habit, she had shut them before going out. Looking into the living room, she saw a scene of confusion over by her writing desk. It was as clear as daylight then that a burglar had forced an entry while she was away. Her first impulse was to go from room to room in search of the intruder, but she decided that, at her age, it might be more prudent to have someone with her. So she went down to fetch the building manager from the basement. By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea while he called the police. Then, her composure regained, she was ready to set off with the manager''s help to look for anyone who might still be lurking in her apartment. They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints. The chaos was almost inconceivable. She had lived in the apartment for thirty years and loved to collect and keep things; and it seemed as though everything she owned had been pulled out and turned over and over. At least, she thought, sorting out the things she should have discarded years ago was now being made easier for her. Then a police inspector arrived with an officer, and she told them how she had found the ransacked apartment. The inspector began to look for fingerprints, while the officer checked that the front-door locks had not been forced, thereby proving that the burglar had either used a master key or climbed in over the balcony. There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewelry the old lady said was not hers. So this apartment was apparently not the burglar''s first stop that day, and he must have been disturbed. The inspector advised her not to stay alone for a few nights. The old lady thought he was a fussy creature, but since the manager agreed with him, she called her daughter and asked for her help with what she called a little spot of bother.","explanation_cn":"课文结尾说老太太把这整件事轻描淡写地称作“一点儿小麻烦”。✓ a little spot of bother."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l59',3,12,59,'Collecting','收藏','限定性定语从句(who/which/that)、非限定性定语从句(, which / … of which)、同位语从句(the belief/chances + that + 完整句、to such an extent that)、原因/让步状语从句(as/since 原因;whatever 让步)、if 虚拟条件(would…if + 过去式)+ 短语动词(NCE3 第三册 Unit 3 无 KS 页,考点由课文结构 + Notes on the text 自取;原创承载·论人为何收藏杂物、收藏作为爱好的种种益处的议论文·题材健康无害;美语化 closet/catalog)','人们往往会积攒东西,有时甚至没意识到自己在这么做。的确,当他们从自己的收藏里翻出一件有用、却不知自己竟拥有的东西时,会有一种惊喜。那些从不必搬家的人,成了各种杂物的收藏者——那些东西只能被称作一堆废物。他们把不用的东西一放好几年,搁在抽屉、壁橱、阁楼里,相信总有一天正好用得上。人上了年纪,还会出于另两个原因积攒物件:一是精力不济,而精力对清理杂物必不可少;二是感情。放久了的东西满是与往昔的联系,于是渐渐获得了超出其本身的价值。有些东西是有意收藏起来以免浪费的。我要举的例子就有细绳和牛皮纸,节俭的人每拆一个包裹就把这两样必备品留下,省得日后再买。收集小玩意儿很容易上瘾。我认识一个人,她总爱从报纸上剪下想买却买不起的衣服图样。她并不富裕,买得起的可能性微乎其微;可她意志又不够坚定,停不下这个习惯。这习惯无害,只是把书桌弄得乱到——每次一打开,纸片就四处飞落。把收藏当作正经爱好则完全是另一回事,好处多多。它为闲暇提供休息,因为端详自己的珍品本身就是一种乐趣。人不必出门去找消遣,因为收藏就在家中。不管收藏的是什么——邮票、唱片、初版书、瓷器、模型汽车,还是玩具动物——总有事可做:从给新入手的藏品找个合适的位置,到在参考书里核对事实。这爱好不仅让人在所选的专题上受教育,也让人在与之有关的一般事物上长进。此外还有别的好处。收藏者想结识志趣相投的人,好求教、交流心得、交换藏品、炫耀最新的收获,于是朋友圈越来越大。很快这爱好还会带来旅行:也许去别的城市开个碰头会,也许为寻一件稀罕标本而出趟远门,因为收藏者并不局限于某一个国家。多年下来,人很可能成了这门爱好的行家,还会被请去做非正式的讲谈——先对小圈子,若讲得好,再对更大的听众。自信就这样滋长起来:先来自精通一门学问,再来自能把它讲出来。收藏,以如此有益的方式占据了闲暇,让人心满意足,再无烦闷的余地。','{"q":"Listen and answer — What in particular does a person gain when he or she becomes a serious collector?","options":["Growing self-confidence","A great deal of money","A bigger house","More free time"],"answer_index":0}'::jsonb,'{"title":"定语从句(限定/非限定) / 同位语从句 / 原因·让步从句 / if 虚拟","intro":"①限定性定语从句 who/which/that 修饰前面的名词:something which they did not know they owned。②非限定性定语从句用逗号隔开,which 可指整件事:energy, which is essential…。③同位语从句由 that 引导,对抽象名词作解释:the belief that…, the chances that…, to such an extent that…。④原因从句 as/since=因为;让步 whatever=不管…。⑤if 虚拟(与现在相反):if + 过去式,主句 would + 原形。","table":{"headers":["用法","引导词","例子"],"rows":[["限定性定语从句","who/which/that","matters which have a bearing on it"],["非限定性定语从句",", which / … of which","energy, which is essential"],["同位语从句","抽象名词 + that","the belief that they may need them"],["原因/让步从句","as/since / whatever","since the collection is at home"]]},"specialRules":[{"rule":"同位语从句里的 that 是纯连词、不作句子成分、不可省去指代含义;定语从句里的 which/that 要在从句中充当成分。","mark":"the belief that…(同位语) / things that I own(定语)"},{"rule":"非限定性从句只能用 which(不用 that);which 可回指前面整件事:…, which made him proud。","mark":", which made him proud"},{"rule":"美式用词:closet(壁橱,英式 cupboard)、catalog(目录,英式 catalogue)。本课已按美语写。","mark":"closet / catalog"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l59',1,NULL,'People tend to amass possessions, sometimes without even being aware of doing so. Indeed, they can have a delightful surprise when they find something useful which they did not know they owned. Those who never have to move house become indiscriminate collectors of what can only be described as clutter. They leave unwanted objects in drawers, closets and attics for years, in the belief that they may one day need just those very things.','人们往往会积攒东西,有时甚至没意识到自己在这么做。的确,当他们翻出一件有用、却不知自己竟拥有的东西时,会有一种惊喜。那些从不必搬家的人,成了各种杂物的收藏者——那些东西只能被称作一堆废物。他们把不用的东西一放好几年,搁在抽屉、壁橱、阁楼里,相信总有一天正好用得上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l59',2,NULL,'As people grow older, they accumulate belongings for two other reasons: a lack of energy, which is essential for clearing things out, and sentiment. Things owned for a long time are full of associations with the past, and so they gradually acquire a value beyond their true worth. Some things are collected deliberately in an attempt to avoid waste, such as string and brown paper, kept by thrifty people whenever a parcel is opened.','人上了年纪,还会出于另两个原因积攒物件:一是精力不济,而精力对清理杂物必不可少;二是感情。放久了的东西满是与往昔的联系,于是渐渐获得了超出其本身的价值。有些东西是有意收藏起来以免浪费的,比如细绳和牛皮纸——节俭的人每拆一个包裹就把它们留下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l59',3,NULL,'Collecting small items can easily become a mania. I know someone who always cuts sketches out of newspapers of clothes that she would like to buy if she had the money. As she is not rich, the chances that she will ever afford such purchases are remote; but she is never strong-minded enough to stop the practice. It is a harmless habit, yet it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction.','收集小玩意儿很容易上瘾。我认识一个人,她总爱从报纸上剪下想买却买不起的衣服图样。她并不富裕,买得起的可能性微乎其微;可她意志又不够坚定,停不下这个习惯。这习惯无害,只是把书桌弄得乱到——每次一打开,纸片就四处飞落。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l59',4,NULL,'Collecting as a serious hobby is quite different, and has many advantages. It provides relaxation for leisure hours, as just looking at one''s treasures is always a joy. One does not have to go out for amusement, since the collection is housed at home. Whatever it consists of — stamps, records, model cars, or toy animals — there is always something to do, from finding the right place for the latest addition to verifying facts in reference books.','把收藏当作正经爱好则完全是另一回事,好处多多。它为闲暇提供休息,因为端详自己的珍品本身就是一种乐趣。人不必出门去找消遣,因为收藏就在家中。不管收藏的是什么——邮票、唱片、模型汽车,还是玩具动物——总有事可做:从给新藏品找合适的位置,到在参考书里核对事实。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l59',5,NULL,'A collector wants to meet like-minded people, to compare notes, and to show off the latest find, and so one''s circle of friends grows. Soon the hobby leads to travel, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. In this way self-confidence grows, first from mastering a subject and then from being able to talk about it. Collecting, by occupying spare time so constructively, makes a person contented, with no room for boredom.','收藏者想结识志趣相投的人,好交流心得、炫耀最新的收获,于是朋友圈越来越大。很快这爱好还会带来旅行:也许为寻一件稀罕标本而出趟远门,因为收藏者并不局限于某一个国家。自信就这样滋长:先来自精通一门学问,再来自能把它讲出来。收藏,以如此有益的方式占据了闲暇,让人心满意足,再无烦闷的余地。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
