INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l59','turn out','',NULL,'/tɜːrn aʊt/','It takes energy to turn out old closets.','清理旧壁橱很费力气。','We turned out the attic last weekend.','上周末我们把阁楼清理了一遍。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l59','cut out','',NULL,'/kʌt aʊt/','She cuts out sketches from newspapers.','她从报纸上剪下图样。','He cut out the coupon from the flyer.','他从传单上剪下优惠券。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l59','show off','',NULL,'/ʃoʊ ɔːf/','Collectors love to show off their latest find.','收藏者爱炫耀最新的收获。','He likes to show off his new car.','他喜欢炫耀他的新车。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l59','be confined to','',NULL,'/bi kənˈfaɪnd tə/','Collectors are not confined to any one country.','收藏者并不局限于某一个国家。','The illness confined her to bed for a week.','这病使她卧床一周。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp1','choice','{"stem":"\"They found something useful ___ they did not know they owned.\"(限定性定从,指物,作宾语)","options":["who","what","which","whose"],"answer_index":2,"stem_cn":"他们找到了自己都不知道拥有的有用之物。","explanation_cn":"限定性定语从句,先行词 something 指物,which 在从句中作动词的宾语。✓ something which they did not know they owned. ✗ who(指人)/ what(不引导定从)/ whose(所属):指物用 which。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp1','choice','{"stem":"\"Those ___ never have to move house become collectors of clutter.\"(限定性定从,指人,作主语)","options":["who","whom","what","which"],"answer_index":0,"stem_cn":"那些从不必搬家的人成了杂物收藏者。","explanation_cn":"限定性定语从句,先行词 Those 指人,who 在从句中作主语。✓ Those who never move house. ✗ which(指物)/ whom(作宾语)/ what:指人作主语用 who。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp1','choice','{"stem":"\"The hobby educates one in matters ___ have some bearing on it.\"(限定性定从,指物,作主语)","options":["who","which","whose","what"],"answer_index":1,"stem_cn":"这一爱好还让人在与之有关的事上长进。","explanation_cn":"限定性定语从句,先行词 matters 指物,which 作从句主语。✓ matters which have some bearing on it. ✗ who(指人)/ whose / what:指物用 which。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp2','choice','{"stem":"\"People lack energy, ___ is essential for clearing things out.\"(非限定性定从,指前面整件事,填关系词)","options":["which","what","it","that"],"answer_index":0,"stem_cn":"人们缺乏精力,而精力对清理杂物至关重要。","explanation_cn":"非限定性定语从句,用逗号隔开,which 回指前面的 energy(或整件事)。✓ energy, which is essential… ✗ that(非限定性不用 that)/ what / it:非限定性用 which。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp2','choice','{"stem":"\"They collect for two reasons, ___ of which are hard to resist.\"(非限定性从句:___ of which 表‘两者都’,填这个词)","options":["none","all","either","both"],"answer_index":3,"stem_cn":"他们出于两个原因收藏,这两个原因都难以抗拒。","explanation_cn":"“…of which”结构:两个原因都难以抗拒,用 both of which。✓ two reasons, both of which are hard to resist. ✗ all(用于三者以上)/ either / none(意思相反):表“两者都”用 both。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp2','choice','{"stem":"\"He gave talks to larger audiences, ___ made him more confident.\"(非限定性定从,指整件事)","options":["what","which","that","and"],"answer_index":1,"stem_cn":"他对更多听众演讲,这让他更自信。","explanation_cn":"非限定性定语从句,which 回指前面整件事(他对更多听众演讲)。✓ …, which made him more confident. ✗ that / what / and:回指整件事用 which。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp3','choice','{"stem":"\"They keep things in the ___ that they may one day need them.\"(名词 + that 同位语从句:‘…的想法’,填这个名词)","options":["way","reason","place","belief"],"answer_index":3,"stem_cn":"他们留着东西,以为总有一天用得上。","explanation_cn":"in the belief that…,“抱着…的想法”;that 引导同位语从句,解释 belief。✓ in the belief that they may need them. ✗ place / way / reason:此处固定名词是 belief。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp3','choice','{"stem":"\"The chances ___ she will ever afford it are remote.\"(the chances + ___ 同位语从句:引导对 chances 的解释,填连词)","options":["that","what","which","whose"],"answer_index":0,"stem_cn":"她买得起的可能性微乎其微。","explanation_cn":"the chances that…,that 引导同位语从句,对抽象名词 chances 作解释。✓ the chances that she will ever afford it. ✗ which / what / whose:同位语从句用 that。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp3','choice','{"stem":"\"It litters her desk to such an extent ___ paper falls out everywhere.\"(to such an extent + ___:引导结果/同位语,填连词)","options":["which","as","what","that"],"answer_index":3,"stem_cn":"它把书桌弄得乱到纸片四处掉落。","explanation_cn":"to such an extent that…,“到了…的程度以至于”;that 引导从句解释 extent。✓ to such an extent that paper falls out. ✗ which / as / what:此结构固定用 that。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp4','choice','{"stem":"\"One need not go out for fun, ___ the collection is at home.\"(引导原因‘因为’,填连词)","options":["since","whether","though","unless"],"answer_index":0,"stem_cn":"不必出门找乐子,因为收藏就在家里。","explanation_cn":"since=“因为”,引导原因从句。✓ since the collection is at home. ✗ though 虽然;✗ unless 除非;✗ whether 是否——都不表原因。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp4','choice','{"stem":"\"___ it consists of, there is always something to do with a collection.\"(‘不管…是什么’,填引导让步的词)","options":["However","Whenever","Whatever","Wherever"],"answer_index":2,"stem_cn":"不管收藏的是什么,总有事可做。","explanation_cn":"whatever=“不管…是什么”,引导让步。✓ Whatever it consists of, there is always something to do. ✗ However 不管多么;✗ Whenever 无论何时;✗ Wherever 无论何地。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp4','choice','{"stem":"\"Collecting is a joy, ___ looking at one''s treasures pleases the eye.\"(表原因‘因为’,填这个连词)","options":["as","but","or","that"],"answer_index":0,"stem_cn":"收藏是种乐趣,因为端详自己的珍品赏心悦目。","explanation_cn":"as=“因为”,引导原因从句。✓ Collecting is a joy, as looking at one''s treasures pleases the eye. ✗ but / or / that:表原因用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp5','choice','{"stem":"\"She cuts out clothes she would buy if she ___ the money.\"(与现在相反虚拟,if 从句用过去式)","options":["will have","having","has","had"],"answer_index":3,"stem_cn":"她剪下若有钱就会买的衣服图样。","explanation_cn":"与现在相反的虚拟,if 从句用一般过去式 had。✓ if she had the money. ✗ has / will have / having:虚拟条件从句用过去式 had。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp5','choice','{"stem":"\"She would like to buy them if she ___ rich.\"(与现在相反虚拟,be 动词用哪种形式)","options":["were","is","will be","be"],"answer_index":0,"stem_cn":"她要是有钱就想买下它们。","explanation_cn":"与现在相反的虚拟,be 动词一律用 were。✓ if she were rich. ✗ is / will be / be:虚拟条件里 be 用 were。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp5','choice','{"stem":"\"Collectors love to show ___ their latest find.\"(show ___:炫耀、展示,填副词)","options":["in","out","up","off"],"answer_index":3,"stem_cn":"收藏者爱炫耀自己最新的收藏。","explanation_cn":"show off,“炫耀、展示”;固定用副词 off。✓ show off the latest find. ✗ in / up / out:固定搭配是 show off。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp6','choice','{"stem":"\"To gather a large amount over time is to ___.\"(“积聚”用哪个词)","options":["spend","waste","amass","lose"],"answer_index":2,"stem_cn":"日积月累地聚拢大量东西。","explanation_cn":"日积月累地聚拢大量东西是 amass。✓ amass possessions. ✗ waste 浪费;✗ lose 丢失;✗ spend 花费——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp6','choice','{"stem":"\"A great enthusiasm that becomes almost an obsession is a ___.\"(“癖好、狂热”用哪个词)","options":["fear","duty","rule","mania"],"answer_index":3,"stem_cn":"近乎着迷的强烈爱好。","explanation_cn":"近乎着迷的强烈爱好是 mania。✓ collecting can become a mania. ✗ duty 责任;✗ fear 恐惧;✗ rule 规则——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',5,'am3_l59_gp6','choice','{"stem":"\"A state of being happy and satisfied is being ___.\"(“心满意足的”用哪个词)","options":["anxious","angry","contented","bored"],"answer_index":2,"stem_cn":"幸福而满足的状态。","explanation_cn":"幸福而满足的状态是 contented。✓ makes a person contented. ✗ bored 无聊;✗ anxious 焦虑;✗ angry 愤怒——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"amass 的意思是:","options":["借出","浪费","丢弃","积聚,大量收集"],"answer_index":3,"explanation_cn":"amass = 积聚、大量收集。✓ amass possessions 积攒东西。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"indiscriminate 的意思是:","options":["精挑细选的","不加选择的","短暂的","昂贵的"],"answer_index":1,"explanation_cn":"indiscriminate = 不加选择的。✓ indiscriminate collectors 什么都收的收藏者。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"clutter 的意思是:","options":["珍宝","家具","工具","一堆杂物"],"answer_index":3,"explanation_cn":"clutter = 一堆杂物。✓ described as clutter 只能算杂物。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"mania 的意思是:","options":["癖好,狂热","厌恶","恐惧","责任"],"answer_index":0,"explanation_cn":"mania = 癖好、狂热。✓ become a mania 变成一种癖好。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"specimen 的意思是:","options":["复制品","废品","标本,样本","礼物"],"answer_index":2,"explanation_cn":"specimen = 标本、样本。✓ a rare specimen 一件稀罕标本。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',6,NULL,'choice','{"stem":"boredom 的意思是:","options":["惊讶","烦闷,无聊","快乐","骄傲"],"answer_index":1,"explanation_cn":"boredom = 烦闷、无聊。✓ no room for boredom 没有烦闷的余地。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',7,NULL,'cloze','{"stem":"第 1 空","context":"People ___1___ possessions without being aware of it. They keep old things in the belief ___2___ they may one day need them. Collecting as a serious hobby provides relaxation, ___3___ looking at one''s treasures is a joy. ___4___ a collection consists of, there is always something to do.","blank_no":1,"options":["amass","waste","lose","hide"],"answer_index":0,"explanation_cn":"amass=积聚,主语 people 用原形。✓ People amass possessions."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',7,NULL,'cloze','{"stem":"第 2 空","context":"People ___1___ possessions without being aware of it. They keep old things in the belief ___2___ they may one day need them. Collecting as a serious hobby provides relaxation, ___3___ looking at one''s treasures is a joy. ___4___ a collection consists of, there is always something to do.","blank_no":2,"options":["that","which","what","whose"],"answer_index":0,"explanation_cn":"in the belief that…,that 引导同位语从句。✓ in the belief that they may need them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',7,NULL,'cloze','{"stem":"第 3 空","context":"People ___1___ possessions without being aware of it. They keep old things in the belief ___2___ they may one day need them. Collecting as a serious hobby provides relaxation, ___3___ looking at one''s treasures is a joy. ___4___ a collection consists of, there is always something to do.","blank_no":3,"options":["as","so","if","or"],"answer_index":0,"explanation_cn":"as=“因为”,引导原因从句。✓ …provides relaxation, as looking at one''s treasures is a joy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',7,NULL,'cloze','{"stem":"第 4 空","context":"People ___1___ possessions without being aware of it. They keep old things in the belief ___2___ they may one day need them. Collecting as a serious hobby provides relaxation, ___3___ looking at one''s treasures is a joy. ___4___ a collection consists of, there is always something to do.","blank_no":4,"options":["Whatever","However","Whenever","Wherever"],"answer_index":0,"explanation_cn":"whatever=“不管…是什么”,引导让步。✓ Whatever a collection consists of…"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',8,NULL,'choice','{"stem":"What in particular does a person gain from becoming a serious collector?","options":["Growing self-confidence","A bigger house","A lot of money","More free time"],"answer_index":0,"explanation_cn":"录音说成为认真的收藏者,最突出的收获是不断增长的自信——先来自精通,再来自能讲出来。✓ growing self-confidence."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',8,NULL,'choice','{"stem":"Why do people who never move house tend to accumulate clutter?","options":["They dislike cleaning","They enjoy shopping","They keep things believing they may need them one day","They are very wealthy"],"answer_index":2,"explanation_cn":"录音说从不搬家的人会攒下杂物,因为他们相信总有一天正好用得上。✓ believing they may need them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',8,NULL,'choice','{"stem":"According to the passage, how does serious collecting affect one''s circle of friends?","options":["It disappears completely","It grows, as collectors meet like-minded people","It shrinks over time","It stays exactly the same"],"answer_index":1,"explanation_cn":"录音说收藏让人结识志趣相投的同好,朋友圈因此不断扩大。✓ circle of friends grows."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',9,NULL,'choice','{"stem":"你想说\"人们缺乏精力,而精力对清理杂物至关重要\"(非限定性从句):","options":["People lack energy, what is essential for clearing things out.","People lack energy, that is essential for clearing things out.","People lack energy, which is essential for clearing things out.","People lack energy which essential for clearing things out."],"answer_index":2,"explanation_cn":"非限定性从句用逗号 + 关系词 which,回指前面的 energy;不用 what、不用 that,从句里要有 is。✓ energy, which is essential… 场合:对前面内容作补充说明。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',9,NULL,'choice','{"stem":"你想说\"他们留着东西,以为总有一天用得上\"(同位语从句 the belief that):","options":["They keep things in the belief that they may one day need them.","They keep things in the belief which they may one day need them.","They keep things in the belief what they may one day need them.","They keep things in belief that they may one day need them."],"answer_index":0,"explanation_cn":"in the belief that…,that 引导同位语从句、纯连词解释 belief;不用 which/what;固定搭配 in the belief that,不能丢 the。✓ in the belief that… 场合:说“抱着…的想法”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',9,NULL,'choice','{"stem":"你想说\"她要是有钱就想买下它们\"(与现在相反虚拟):","options":["She would like to buy them if she has the money.","She would like to buy them if she have the money.","She will like to buy them if she had the money.","She would like to buy them if she had the money."],"answer_index":3,"explanation_cn":"与现在相反的虚拟:if 从句用过去式 had,主句 would + 原形 like;不用 has、不用 will like、不用 have。✓ would like … if she had the money. 场合:对现在的与事实相反的假设。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"amass 的意思是:","options":["积聚,大量收集","借出","浪费","丢弃"],"answer_index":0,"explanation_cn":"amass = 积聚、大量收集。✓ amass possessions."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"boredom 的意思是:","options":["惊讶","烦闷,无聊","骄傲","快乐"],"answer_index":1,"explanation_cn":"boredom = 烦闷、无聊。✓ no room for boredom."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"\"Those ___ never have to move house become collectors of clutter.\"(限定性定从,指人)","options":["what","whom","who","which"],"answer_index":2,"stem_cn":"那些从不必搬家的人成了杂物收藏者。","explanation_cn":"限定性定语从句,先行词 Those 指人,who 作从句主语。✓ Those who never move house. ✗ which / whom / what。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"\"___ a collection consists of, there is always something to do.\"(‘不管…是什么’,填引导让步的词)","options":["Whatever","However","Wherever","Whenever"],"answer_index":0,"stem_cn":"不管收藏的是什么,总有事可做。","explanation_cn":"whatever=“不管…是什么”,引导让步。✓ Whatever a collection consists of… ✗ However / Whenever / Wherever。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"\"show off\" 的意思是:","options":["躲开","关掉","炫耀、展示","推迟"],"answer_index":2,"explanation_cn":"show off = 炫耀、展示。✓ show off the latest find."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"\"be confined to\" 的意思是:","options":["局限于、限于","超过","属于","来自"],"answer_index":0,"explanation_cn":"be confined to = 局限于、限于。✓ collectors are not confined to any one country."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"Why do older people tend to keep more belongings?","options":["They plan to sell them","They all have larger homes","They lack the energy to clear things out, and grow attached to them","They are required to by law"],"answer_index":2,"passage":"People tend to amass possessions, sometimes without even being aware of doing so. Indeed, they can have a delightful surprise when they find something useful which they did not know they owned. Those who never have to move house become indiscriminate collectors of what can only be described as clutter. They leave unwanted objects in drawers, closets and attics for years, in the belief that they may one day need just those very things. As people grow older, they accumulate belongings for two other reasons: a lack of energy, which is essential for clearing things out, and sentiment. Things owned for a long time are full of associations with the past, and so they gradually acquire a value beyond their true worth. Some things are collected deliberately in an attempt to avoid waste. Among these I would list string and brown paper, kept by thrifty people whenever a parcel is opened, to save buying these two requisites. Collecting small items can easily become a mania. I know someone who always cuts sketches out of newspapers of clothes that she would like to buy if she had the money. As she is not rich, the chances that she will ever afford such purchases are remote; but she is never strong-minded enough to stop the practice. It is a harmless habit, yet it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction. Collecting as a serious hobby is quite different, and has many advantages. It provides relaxation for leisure hours, as just looking at one''s treasures is always a joy. One does not have to go out for amusement, since the collection is housed at home. Whatever it consists of — stamps, records, first editions, china, model cars, or toy animals — there is always something to do, from finding the right place for the latest addition to verifying facts in reference books. The hobby educates a person not only in the chosen subject but also in general matters which have some bearing on it. There are other benefits too. A collector wants to meet like-minded people, to get advice, to compare notes, and to show off the latest find, and so one''s circle of friends grows. Soon the hobby leads to travel, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. Over the years one may well become an authority on the subject, and may be asked to give informal talks, first to small gatherings and then, if successful, to larger audiences. In this way self-confidence grows, first from mastering a subject and then from being able to talk about it. Collecting, by occupying spare time so constructively, makes a person contented, with no room for boredom.","explanation_cn":"课文说人年老后攒东西有两个原因:一是没了清理杂物的精力,二是对旧物生出感情。✓ lack of energy and sentiment."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"How does a serious hobby help build self-confidence?","options":["By moving house often","First from mastering a subject, then from being able to talk about it","By avoiding other people","By making a lot of money"],"answer_index":1,"passage":"People tend to amass possessions, sometimes without even being aware of doing so. Indeed, they can have a delightful surprise when they find something useful which they did not know they owned. Those who never have to move house become indiscriminate collectors of what can only be described as clutter. They leave unwanted objects in drawers, closets and attics for years, in the belief that they may one day need just those very things. As people grow older, they accumulate belongings for two other reasons: a lack of energy, which is essential for clearing things out, and sentiment. Things owned for a long time are full of associations with the past, and so they gradually acquire a value beyond their true worth. Some things are collected deliberately in an attempt to avoid waste. Among these I would list string and brown paper, kept by thrifty people whenever a parcel is opened, to save buying these two requisites. Collecting small items can easily become a mania. I know someone who always cuts sketches out of newspapers of clothes that she would like to buy if she had the money. As she is not rich, the chances that she will ever afford such purchases are remote; but she is never strong-minded enough to stop the practice. It is a harmless habit, yet it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction. Collecting as a serious hobby is quite different, and has many advantages. It provides relaxation for leisure hours, as just looking at one''s treasures is always a joy. One does not have to go out for amusement, since the collection is housed at home. Whatever it consists of — stamps, records, first editions, china, model cars, or toy animals — there is always something to do, from finding the right place for the latest addition to verifying facts in reference books. The hobby educates a person not only in the chosen subject but also in general matters which have some bearing on it. There are other benefits too. A collector wants to meet like-minded people, to get advice, to compare notes, and to show off the latest find, and so one''s circle of friends grows. Soon the hobby leads to travel, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. Over the years one may well become an authority on the subject, and may be asked to give informal talks, first to small gatherings and then, if successful, to larger audiences. In this way self-confidence grows, first from mastering a subject and then from being able to talk about it. Collecting, by occupying spare time so constructively, makes a person contented, with no room for boredom.","explanation_cn":"课文说自信是这样长起来的:先来自精通一门学问,再来自能把它讲给别人听。✓ mastering then talking about it."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"What does the writer say a serious collector eventually gains?","options":["A much larger house","Fame and fortune","Self-confidence and contentment","A quiet life alone"],"answer_index":2,"audio":"People tend to amass possessions, sometimes without even being aware of doing so. Indeed, they can have a delightful surprise when they find something useful which they did not know they owned. Those who never have to move house become indiscriminate collectors of what can only be described as clutter. They leave unwanted objects in drawers, closets and attics for years, in the belief that they may one day need just those very things. As people grow older, they accumulate belongings for two other reasons: a lack of energy, which is essential for clearing things out, and sentiment. Things owned for a long time are full of associations with the past, and so they gradually acquire a value beyond their true worth. Some things are collected deliberately in an attempt to avoid waste. Among these I would list string and brown paper, kept by thrifty people whenever a parcel is opened, to save buying these two requisites. Collecting small items can easily become a mania. I know someone who always cuts sketches out of newspapers of clothes that she would like to buy if she had the money. As she is not rich, the chances that she will ever afford such purchases are remote; but she is never strong-minded enough to stop the practice. It is a harmless habit, yet it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction. Collecting as a serious hobby is quite different, and has many advantages. It provides relaxation for leisure hours, as just looking at one''s treasures is always a joy. One does not have to go out for amusement, since the collection is housed at home. Whatever it consists of — stamps, records, first editions, china, model cars, or toy animals — there is always something to do, from finding the right place for the latest addition to verifying facts in reference books. The hobby educates a person not only in the chosen subject but also in general matters which have some bearing on it. There are other benefits too. A collector wants to meet like-minded people, to get advice, to compare notes, and to show off the latest find, and so one''s circle of friends grows. Soon the hobby leads to travel, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. Over the years one may well become an authority on the subject, and may be asked to give informal talks, first to small gatherings and then, if successful, to larger audiences. In this way self-confidence grows, first from mastering a subject and then from being able to talk about it. Collecting, by occupying spare time so constructively, makes a person contented, with no room for boredom.","explanation_cn":"课文说收藏以有益的方式占据闲暇,让人自信、心满意足,再无烦闷。✓ self-confidence and contentment."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l59',10,NULL,'choice','{"stem":"Where might a serious collector''s hobby eventually lead them?","options":["To give up all other hobbies","To travel, even a trip abroad for a rare specimen","To stop meeting people","To move overseas permanently"],"answer_index":1,"audio":"People tend to amass possessions, sometimes without even being aware of doing so. Indeed, they can have a delightful surprise when they find something useful which they did not know they owned. Those who never have to move house become indiscriminate collectors of what can only be described as clutter. They leave unwanted objects in drawers, closets and attics for years, in the belief that they may one day need just those very things. As people grow older, they accumulate belongings for two other reasons: a lack of energy, which is essential for clearing things out, and sentiment. Things owned for a long time are full of associations with the past, and so they gradually acquire a value beyond their true worth. Some things are collected deliberately in an attempt to avoid waste. Among these I would list string and brown paper, kept by thrifty people whenever a parcel is opened, to save buying these two requisites. Collecting small items can easily become a mania. I know someone who always cuts sketches out of newspapers of clothes that she would like to buy if she had the money. As she is not rich, the chances that she will ever afford such purchases are remote; but she is never strong-minded enough to stop the practice. It is a harmless habit, yet it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction. Collecting as a serious hobby is quite different, and has many advantages. It provides relaxation for leisure hours, as just looking at one''s treasures is always a joy. One does not have to go out for amusement, since the collection is housed at home. Whatever it consists of — stamps, records, first editions, china, model cars, or toy animals — there is always something to do, from finding the right place for the latest addition to verifying facts in reference books. The hobby educates a person not only in the chosen subject but also in general matters which have some bearing on it. There are other benefits too. A collector wants to meet like-minded people, to get advice, to compare notes, and to show off the latest find, and so one''s circle of friends grows. Soon the hobby leads to travel, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country. Over the years one may well become an authority on the subject, and may be asked to give informal talks, first to small gatherings and then, if successful, to larger audiences. In this way self-confidence grows, first from mastering a subject and then from being able to talk about it. Collecting, by occupying spare time so constructively, makes a person contented, with no room for boredom.","explanation_cn":"课文说这爱好很快带来旅行,甚至为寻一件稀罕标本而出趟远门,因为收藏者不限于一国。✓ travel, a trip abroad for a specimen."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
